import {
  Frame,
  obstacles,
  Run,
  canMantle,
  ground,
  lowerRoofDrops,
  GameMode,
} from "./model";
import {
  techniques,
  isSwing,
  comboNames,
  Technique,
  chainSections,
  obstacleEnd,
} from "./combos";

export const options = [
  "run",
  "jump",
  "long-jump",
  "front-flip",
  "dash",
  "hurdle",
  "speed",
  "one-hand",
  "safety",
  "lazy",
  "kong",
  "slide",
  "kash",
  "wall",
  "wall-climb",
  "wall-run",
  "dive",
  "roll",
  "catch",
  "landing",
  ...techniques,
  ...comboNames.map((name) => `combo:${name}` as const),
] as const;
export type Preview = (typeof options)[number];
export function minimumPreviewSpeed(move: Preview) {
  return move === "front-flip"
    ? 8
    : move === "dive"
      ? 10.5
      : isSwing(move as Technique) || move === "catch"
        ? 12
        : 6;
}

export function previewObstacles(move: Preview) {
  if (move === "front-flip")
    return obstacles.filter(
      (o) => o.route === "lower" && o.x === lowerRoofDrops[0].x,
    );
  if (move.startsWith("combo:"))
    return obstacles.filter(
      (o) =>
        o.combo === move.slice(6) &&
        (o.route === "lower" ||
          !obstacles.some(
            (item) => item.combo === move.slice(6) && item.route === "lower",
          )),
    );
  const o = obstacles.find((item) =>
    item.technique === move
      ? true
      : move === "wall-run"
        ? item.feature === "wall-billboard"
        : move === "dive"
          ? item.feature === "window"
          : move === "kash"
            ? canMantle(item)
            : move === "safety" || move === "hurdle" || move === "one-hand"
              ? item.kind === "vault"
              : item.vault === move,
  );
  return o ? [o] : [];
}

export function simulateChain(
  name: (typeof comboNames)[number],
  speed: number,
  mode: GameMode = "standard",
  releaseAt = 0.55,
) {
  const group = previewObstacles(`combo:${name}`);
  const g = new Run();
  g.start(0, false, mode);
  const section = chainSections.find((item) => item.name === name);
  const expanded = Boolean(section);
  g.x = section ? Math.max(section.start, group[0].x - 8) : group[0].x - 3;
  g.upper = group[0].route === "upper";
  g.y = ground(g.x, g.upper);
  g.speed = speed;
  g.previous = g.frame();
  const frames: Frame[] = [],
    pressed = new Set<number>();
  for (
    let tick = 0;
    tick < 1200 &&
    g.phase === "running" &&
    (g.x < obstacleEnd(group[group.length - 1]) + 3 ||
      !g.grounded ||
      Boolean(g.traversal));
    tick++
  ) {
    const next = g.next();
    if (
      !g.grounded &&
      !g.traversal &&
      g.vy < -10 &&
      g.y - ground(g.x, g.upper) < 1.1
    )
      g.action("down");
    if (
      g.traversal?.move === "special" &&
      isSwing(g.traversal.technique) &&
      !g.traversal.released &&
      g.frame().progress > releaseAt
    )
      g.action("forward");
    if (
      next &&
      (!expanded || next.combo === name) &&
      next.kind !== "drop" &&
      !g.traversal &&
      g.grounded &&
      !pressed.has(next.x) &&
      next.x - g.x <= (next.kind === "gap" ? 1.1 : 1.9)
    ) {
      g.action(
        next.kind === "slide"
          ? "down"
          : next.feature === "window" ||
              (next.combo === "Final Relay" && next.kind === "gap")
            ? "forward"
            : "up",
      );
      pressed.add(next.x);
    }
    g.step();
    frames.push(g.frame());
  }
  return { run: g, frames, obstacles: group };
}

export function framesFor(
  move: Preview,
  entrySpeed: number,
  releaseAt = 0.55,
): Frame[] {
  const speed = Math.max(minimumPreviewSpeed(move), entrySpeed);
  if (move.startsWith("combo:"))
    return simulateChain(
      move.slice(6) as (typeof comboNames)[number],
      speed,
      "standard",
      releaseAt,
    ).frames;

  const g = new Run();
  g.start();
  g.speed = speed;
  const o = previewObstacles(move)[0];
  if (o) {
    g.x = o.x - (move === "safety" ? 0.2 : isSwing(o.technique) ? 3.1 : 2);
    g.y = ground(o.x, o.route === "upper");
    g.upper = o.route === "upper";
  }
  if (move === "slide") g.x = 88.8;
  if (move === "wall") g.x = 288;
  if (move === "wall-climb") g.x = 113;
  if (move === "roll") {
    g.x = 196;
    g.y = 3.3;
    g.upper = true;
  }
  if (move === "landing") {
    g.x = 196;
    g.y = 3.3;
    g.upper = true;
  }
  if (move === "catch") {
    g.x = 70;
    g.grounded = false;
  }
  if (move === "front-flip") {
    g.x = lowerRoofDrops[0].x - 0.45;
    g.y = ground(g.x, false);
    g.upper = false;
  }
  g.previous = g.frame();
  const frames: Frame[] = [g.frame()];
  let signatureSeen = false,
    settle = 0;
  for (
    let tick = 0;
    tick < (move === "run" ? 100 : 600) && g.phase === "running";
    tick++
  ) {
    if (move === "front-flip" && (tick === 0 || tick === 12)) g.action("up");
    if (move === "front-flip" && g.vy < 0 && g.y < ground(g.x, false) + 1.8)
      g.action("down");
    if (tick === 12 && (move === "jump" || move === "long-jump"))
      g.speed = speed;
    if (
      tick === (move === "safety" ? 0 : 12) &&
      ((o && move !== "front-flip") ||
        move === "jump" ||
        move === "wall" ||
        move === "wall-climb")
    )
      g.action(move === "dive" ? "forward" : "up");
    if (tick === 12 && move === "long-jump") g.action("forward");
    if (tick === 26 && move === "catch") g.action("up");
    if (tick === 8 && move === "slide") g.action("down");
    if (move === "roll" && !g.grounded && g.y < 2.5 && g.y > 1)
      g.action("down");
    if (
      g.traversal?.move === "special" &&
      isSwing(g.traversal.technique) &&
      !g.traversal.released &&
      g.frame().progress > releaseAt
    )
      g.action("forward");
    g.step();
    if (
      g.traversal?.move === "vault" &&
      (move === "hurdle" || move === "one-hand")
    ) {
      g.traversal.vault = move;
      g.vault = move;
    }
    frames.push(g.frame());
    const f = g.frame();
    if (f.move !== "run" && f.move !== "fall") signatureSeen = true;
    if (
      signatureSeen &&
      !g.traversal &&
      g.grounded &&
      (f.move === "run" || f.move === "land" || f.move === "heavy-land")
    ) {
      settle++;
      // Stop before the course introduces another obstacle into this isolated study.
      const next = g.next();
      if (settle > 24 || (next && next.x - g.x < 0.7)) break;
    } else settle = 0;
  }
  return frames;
}
